export const GAME_THEORY = {
  definitions: { nashEquilibrium:"A stable state where no player can improve their outcome by unilaterally changing strategy, given all other players' strategies are fixed.", dominantStrategy:"A strategy that produces the best outcome for a player regardless of what other players choose.", zeroSum:"A game where one player's gain exactly equals another's loss — total payoff is constant.", nonZeroSum:"A game where the combined payoffs can increase or decrease — cooperation can create mutual gain.", signalingGame:"A game where one player (the sender) has private information and the other (receiver) must interpret signals to infer it.", mixedStrategy:"A player randomizes over possible strategies to prevent opponents from exploiting a predictable pattern." },
  countStrategies: { count30:{ label:"3-0 Count", pitcherNE:"Throw fastball — maximizes strike probability, avoids walk, avoids favorable hitter's count deepening.", hitterNE:"Sit on fastball — highest probability pitch, maximize damage opportunity.", insight:"3-0 is the most pitcher-disadvantaged count. Both sides know a fastball is coming. The NE is: pitcher throws fastball, hitter swings — yet 'take' signs still dominate. This is a deviation from Nash driven by organizational heuristics and risk aversion." }, count32:{ label:"3-2 Count", pitcherNE:"Mixed strategy: off-speed to disrupt timing, but fastball if command is uncertain.", hitterNE:"Expand zone awareness — must protect plate, cannot take borderline pitches.", insight:"3-2 forces both sides into mixed strategies. Optimal pitcher strategy is randomized between fastball and secondary. Hitters who can identify pitch type early gain massive EV advantage. This is the count where pitch tunneling matters most." }, countGeneral:{ fastballUsage:"Fastball usage declines monotonically as strike count increases — pitchers shift to off-speed to induce weak contact and generate swings on pitches outside the zone.", battersWithTwoStrikes:"Zone expansion is the empirically dominant hitter strategy with two strikes — contact rate matters more than power, so hitters must expand to avoid strikeouts.", insight:"Swartz (SABR 2013): 'Pitchers in hitter's counts should throw more fastballs, in pitcher's counts more off-speed.' The mixed strategy NE in high leverage counts is the least exploited edge in player evaluation." } },
  inGameGames: { pitcherSwitching:{ structure:"Manager (player A) vs opposing hitter (player B). Manager chooses LHP/RHP; hitter has L/R platoon advantage. Simultaneous decision with imperfect information.", nashOutcome:"Platoon-neutral matchups are the NE: manager plays the matchup, hitter cannot gain additional advantage. Over-reliance on platoon advantage by either side is exploitable.", insight:"The optimal managerial strategy is not always the platoon matchup — it is the strategy the opponent cannot profitably respond to. This is why elite relievers are valuable: they collapse the opponent's mixed strategy options." }, firstPitch:{ insight:"First-pitch strike rate is the highest-leverage count variable. Pitchers who get ahead 0-1 face a dramatically improved NE set across all subsequent pitches. Getting ahead first pitch is a dominant strategy for pitchers with good command." } },
  pitchOptimization: { tunneling:"Pitch tunneling exploits the batter's perceptual limitations — pitches that share a flight path until the decision point (approx. 23 feet) and then diverge create an unsolvable mixed strategy problem for the hitter. This is the physical manifestation of a Nash-dominant pitch design." },
  marketGames: { freeAgency:{ structure:"All-pay auction: multiple teams bid on a player. Highest bidder wins player at their bid price. Losers lose nothing but gain nothing.", nashOutcome:"Teams systematically overbid for top free agents relative to WAR-based value — winner's curse effect. The expected payoff for winning is negative in high-demand auctions.", insight:"The correct free agent strategy is to identify the second tier: players valued near their true WAR where competition is lower and winner's curse is minimized. Bidding on consensus top targets is a negative-EV strategy in aggregate." }, contractNegotiation:{ structure:"Sequential bargaining game: player agent makes offer, team counter-offers, repeat until agreement or deadline.", outcome:"The party with more alternatives (BATNA) and lower deadline urgency holds more leverage. Arbitration-eligible players gain leverage from the transparent comparable system.", insight:"Teams that invest in strong BATNA positions (deep farm system, internal alternatives) systematically outperform in contract negotiations by reducing the cost of walking away." }, draftCollegeVsHS:{ structure:"Prisoner's dilemma across all 30 teams: if all teams draft college-safe picks, the expected value of each team's draft is mediocre but predictable. If one team takes HS upside swings while others draft college, that team captures asymmetric upside.", nashOutcome:"League-wide NE shifts toward college players as risk aversion increases — but individual team EV is maximized by drafting HS players when the market over-weights college safety." }, draftBonusPrisonersDilemma:{ insight:"Bonus pool allocation is a coordination game. Teams that routinely exceed slot on high-upside picks and save slot elsewhere (Astros/Cardinals model) capture EV from teams that allocate evenly. The league-wide NE would be for all teams to slot correctly — but individual deviation is profitable until slot penalties eliminate the edge." } },
  simulationInsights: { fivePlayerGame:{ rules:"Goldman (2016): Five teams each offseason try to sign one of five available free agents across three tiers. Payoffs depend on which tier player each team lands and which teams they beat out.", outcomes:"Teams that commit early to top-tier targets ('go aggressive') beat teams that wait — but if all teams go aggressive, surplus value collapses. The optimal strategy depends on reading opponent intent.", oaklandStrategy:"The A's historically exploited the NE breakdown by targeting Tier 2 players at Tier 3 prices when all competitors were bidding on Tier 1 — positive EV through strategic differentiation.", troutParadox:"Mike Trout's below-market extensions represent a deviation from player-optimal strategy — but reveal that non-monetary payoffs (location, stability, personal preference) alter the true utility function.", insight:"The offseason market is not a simultaneous auction — it is a sequential game with private information about each team's valuation and budget. Teams that signal false valuations (poker strategy) gain systematic advantages." } },
  nextMoneyball: { thesis:"Swartz (SABR 2013) argued that game theory is the next frontier of baseball analytics — the Moneyball era identified market inefficiencies in observable stats (OBP), but the next edge lies in strategic interaction: how pitchers and hitters adapt to each other in real time.", swartz2013:"Identified mixed strategy equilibria in pitch selection by count. Found systematic deviations from Nash in both pitcher and hitter behavior — exploitable edges that persist because they require behavioral change, not just information.", marketEdge:"The deepest edge in modern baseball: teams that train pitchers and hitters to play closer to mixed strategy equilibria will gain measurable performance improvements over teams relying on heuristics and scouting intuition alone.", studeman2013:"Showed that first-pitch strategy is a dominant factor in game outcomes — teams systematically underweight first-pitch strike investment in pitcher development.", prediction:"The next Moneyball will be a team that systematically uses game theory to optimize in-game decision-making: pitch sequencing, defensive shifts, lineup construction, and bullpen deployment simultaneously." },
};

export const BEHAVIORAL_BIASES = {
  confirmationBias: { definition:"The tendency to search for, interpret, and recall information in a way that confirms one's pre-existing beliefs.", scoutingApplication:"Scouts who've labeled a player as a 'bust' or 'can't miss' filter subsequent observations through that lens. Once a grade is set mentally, contradictory evidence is discounted.", analystApplication:"Analysts who build a model favoring a player will dismiss Statcast data that contradicts the model rather than updating the model.", counterMeasure:"Pre-commitment to explicit decision criteria before seeing a player. Structured adversarial review — assign one scout to argue against the consensus.", source:"Kahneman (2011) Thinking Fast and Slow; confirmed in scouting contexts by Lewis (2003) Moneyball." },
  recencyBias: { definition:"Overweighting recent events relative to base rates when making probability estimates.", scoutingApplication:"A prospect who goes 0-for-4 in the game a scout attends gets a lower hit tool grade than his season-long .310 average justifies.", draftApplication:"Teams reach for players who had strong spring performances over players with better 3-year track records but mediocre recent games.", counterMeasure:"Weight multi-year samples over in-person observation windows. Explicit regression-to-mean adjustments in projection models.", source:"Tversky & Kahneman (1974) Judgment Under Uncertainty; applied in fantasy/DFS literature extensively." },
  lossAversion: { definition:"Losses loom approximately 2x larger than equivalent gains in human psychology (Kahneman-Tversky Prospect Theory).", tradeApplication:"Teams are reluctant to trade prospects they already own even when WAR calculations clearly favor the trade — endowment effect on farm assets.", analystApplication:"GMs overvalue existing roster players relative to available alternatives — the 'sunk cost' of previous investment distorts current decision-making.", counterMeasure:"Pre-mortem analysis: assume the trade/signing failed — what would the reason be? Forces explicit acknowledgment of downside scenarios.", source:"Kahneman & Tversky (1979) Prospect Theory; Thaler (1980) Mental Accounting." },
  anchoringBias: { definition:"Over-reliance on the first piece of information encountered when making decisions.", draftApplication:"Early consensus rankings anchor team boards even when internal models produce different values. Teams rarely deviate more than 5 spots from consensus despite divergent internal grades.", tradeApplication:"First offer in a trade sets the anchor — teams that receive first offers consistently outperform teams that make first offers in outcome analysis.", counterMeasure:"Develop internal rankings completely before consuming external sources. Make first offers in negotiations when internal value is higher than expected market anchor.", source:"Tversky & Kahneman (1974); extensively documented in negotiation research." },
  elFarolEffect: { definition:"Arthur (1994): El Farol bar problem — if everyone uses the same prediction model to decide whether to attend (and avoid if expected crowded), the model destroys itself. Bounded rationality leads to heterogeneous strategies.", baseballApplication:"The market for undervalued player types (OBP in Moneyball era) corrects when all teams adopt the same inefficiency-targeting model. The edge disappears the moment it becomes consensus.", minorityGame:"The optimal fantasy/market strategy is the minority strategy: winning requires identifying what the majority is doing and doing the opposite. Being correct but consensus adds zero value.", implication:"SKIP's edge is identifying metrics and player types that the majority of the market is either ignoring or systematically mispricing — the moment a metric becomes universally adopted, its predictive alpha goes to zero.", boundedRationality:"Teams and analysts cannot process all available information optimally — they use heuristics. SKIP systematically models these heuristics to predict where market mispricing will occur." },
  fantasyPsychology: { gladwellTest:"Fantasy baseball is a test of whether you can overcome cognitive biases faster than 11 other people in your league — skill is real but manifests as bias-avoidance, not prediction accuracy.", winProbability:"Expected wins in a standard 12-team roto league: 8.33%. Consistent 60%+ win rates over 5+ seasons reflect genuine skill, not variance. But most owners mistake 2-3 year runs for skill.", correlated:"DFS optimal lineups are correlated stacks (same game, same team) because weather/pitching matchup affects all players on a team simultaneously. Uncorrelated lineups minimize variance but also minimize upside.", biasesInFantasy:{ nameism:"Drafting recognizable names over equal statistical profiles — veteran bias is measurable in ADP across all platforms.", positionScarcity:"Overvaluing positional scarcity (C, SS) relative to actual statistical contribution — catchers are consistently overdrafted relative to WAR.", streakChasing:"Buying high on streaking players at precisely the moment regression-to-mean is most likely — recency bias in its purest fantasy form.", sunkCost:"Refusing to drop players drafted in early rounds even after evidence of injury or underperformance — endowment effect on roster assets." } },
};

