export const FV_METHODOLOGY = {
  whatItIs:"SKIP's Future Value grade (eFV) projects a prospect's realistic career outcome on the traditional 20-80 scouting scale — but unlike a scout's shorthand, eFV isn't rounded to the nearest 5. Two prospects a few ranks apart get two different numbers instead of the same tied grade.",
  inputs:[
    { label:'Board Position', weight:'Primary',   desc:"A prospect's rank in SKIP's combined Top-100 (batters and pitchers share one list). Maps onto a smooth curve — roughly 70 at #1 down to the low 40s at #100 — matching the shape of published industry Top-100 lists rather than a flat distribution." },
    { label:'Level-Relative Performance', weight:'Secondary', desc:"How far a prospect's current OPS (hitters) or ERA / K-rate (pitchers) sits from the median of SKIP's tracked pool at a comparable stage. Deliberately small — a week of stats can't override the underlying rank — but large enough that a real breakout or slump moves the number." },
    { label:'Age-for-Level', weight:'Tertiary', desc:'A player performing young for their level gets a small bump — more runway before a theoretical peak. Old-for-level gets a small discount — less projection remaining.' },
  ],
  outputRange:'35–70 · whole numbers only',
  whyContinuous:"A bucketed grade (45, 50, 55…) works fine for one scout describing one player out loud. It falls apart once you're differentiating 100 of them — dozens end up tied with no way to rank within the tie. Keeping the output continuous doesn't pretend scouting is more precise than it is; the underlying inputs (rank, stat line, age) are exact, so there's no reason to round the output.",
  warAnchors:[[35,0.3],[40,1.0],[45,2.5],[50,4.5],[55,7.0],[60,10.0],[65,12.5],[70,15.0]],
  riskBands:[
    { band:'Low',    color:'teal',  desc:'Advanced level (AAA / MLB-adjacent), age at or above the typical benchmark for that level. Track record is established; variance is mostly in ceiling, not floor.' },
    { band:'Medium', color:'amber', desc:'Mid-level (A+ through AA), age roughly in line with level expectations. Standard developmental variance.' },
    { band:'High',   color:'rust',  desc:'Lower-level (Rookie / A ball) and/or meaningfully young for level. Long developmental runway still ahead — highest bust rate, but also the widest range of outcomes.' },
  ],
  movers:"eFV recomputes automatically every time live MLB stats refresh — it isn't a number someone re-types by hand. The eFV Movers panel on the Prospects tab diffs that live grade against a fixed preseason snapshot, so every mover shown there is driven by real, in-season performance drift.",
  outcomeGrounding:"SKIP validates the eFV curve the same way the Draft Big Board validates its pre-draft ranking against actual results: once a prospect graduates to the majors, their eFV at graduation and their realized production become a permanent pair in the record, not a grade that quietly disappears. A model whose top grades don't outproduce its lower ones over time is a model that needs recalibrating.",
};

